import type { WhoDataset } from './whoData';

// The data file is generated by `npm run who:data` and may not exist yet. A glob
// import builds either way, and keeps the data in its own chunk, loaded on demand.
const dataFiles = import.meta.glob<{ default: WhoDataset }>('./data/whoGrowthData.json');

/** Loads the WHO reference data, or null if it has not been generated. */
export async function loadWhoData(): Promise<WhoDataset | null> {
  const load = dataFiles['./data/whoGrowthData.json'];
  return load ? (await load()).default : null;
}
